"""Deep semantic map of FMZ JavaScript strategy 数字货币期货双均线拐点策略教学.md.

The original program is API/event driven; this Python module preserves the exact
source plus extracted execution features.  Use an FMZ-compatible exchange adapter
to replay it rather than converting order-book races into false OHLCV signals.
"""
SOURCE_FILE = '数字货币期货双均线拐点策略教学.md'
SOURCE_FEATURES = ['var ', 'for ', 'while ', 'exchange.', '_C(', 'Sleep(', 'GetRecords']
SOURCE_FIDELITY_NOTES = ['FMZ JavaScript is event/API driven. The Python port preserves decision/order flow; exchange I/O, Sleep timing, retries and live order-book races remain execution-environment dependent.']
ORIGINAL_JAVASCRIPT = '/*backtest\nstart: 2021-09-01 00:00:00\nend: 2021-12-02 00:00:00\nperiod: 1h\nbasePeriod: 5m\nexchanges: [{"eid":"Futures_Binance","currency":"ETH_USDT"}]\n*/\n\nvar LONG = 1 \nvar SHORT = -1\nvar IDLE = 0\n\nfunction getPosition(positions, direction) {\n    var ret = {Price : 0, Amount : 0, Type : ""}\n    _.each(positions, function(pos) {\n        if (pos.Type == direction) {\n            ret = pos\n        }\n    })\n    return ret \n}\n\nfunction cancellAll() {\n    while (true) {\n        var orders = _C(exchange.GetOrders)\n        if (orders.length == 0) {\n            break\n        } else {\n            for (var i = 0 ; i < orders.length ; i++) {\n                exchange.CancelOrder(orders[i].Id, orders[i])\n                Sleep(500)\n            }\n        }\n        Sleep(500)\n    }\n}\n\nfunction cover(tradeFunc, direction) {\n    var mapDirection = {"closebuy": PD_LONG, "closesell": PD_SHORT}\n    var positions = _C(exchange.GetPosition)\n    var pos = getPosition(positions, mapDirection[direction])\n    if (pos.Amount > 0) {\n        cancellAll()\n        exchange.SetDirection(direction)\n        if (tradeFunc(-1, pos.Amount)) {\n            return true \n        } else {\n            return false \n        }\n    }\n    return true \n}\n\nfunction main() {\n    if (okexSimulate) {\n        exchange.IO("simulate", true) // 切换到OKEX V5模拟盘测试 \n        Log("切换到OKEX V5模拟盘")\n    }    \n    exchange.SetContractType(ct)\n    var state = IDLE\n    var holdPrice = 0\n    var preTime = 0\n\n    while (true) {\n        var r = _C(exchange.GetRecords)\n        var l = r.length\n        if (l < Math.max(ema1Period, ema2Period)) {\n            Sleep(1000)\n            continue\n        }\n        var ema1 = TA.EMA(r, ema1Period)\n        var ema2 = TA.EMA(r, ema2Period)\n        \n        // 画图\n        $.PlotRecords(r, \'K线\')\n        if(preTime !== r[l - 1].Time){\n            $.PlotLine(\'ema1\', ema1[l - 2], r[l - 2].Time)\n            $.PlotLine(\'ema2\', ema2[l - 2], r[l - 2].Time)\n            \n            $.PlotLine(\'ema1\', ema1[l - 1], r[l - 1].Time)\n            $.PlotLine(\'ema2\', ema2[l - 1], r[l - 1].Time)\n            preTime = r[l - 1].Time\n        } else {\n            $.PlotLine(\'ema1\', ema1[l - 1], r[l - 1].Time)\n            $.PlotLine(\'ema2\', ema2[l - 1], r[l - 1].Time)\n        }\n        \n        var up = (ema1[l - 2] > ema1[l - 3] && ema1[l - 4] > ema1[l - 3]) && (ema2[l - 2] > ema2[l - 3] && ema2[l - 4] > ema2[l - 3])\n        var down = (ema1[l - 2] < ema1[l - 3] && ema1[l - 4] < ema1[l - 3]) && (ema2[l - 2] < ema2[l - 3] && ema2[l - 4] < ema2[l - 3])\n        if (up && (state == SHORT || state == IDLE)) {\n            if (state == SHORT && cover(exchange.Buy, "closesell")) {\n                state = IDLE\n                holdPrice = 0\n                $.PlotFlag(r[l - 1].Time, \'coverShort\', \'CS\')\n            }\n            exchange.SetDirection("buy")\n            if (exchange.Buy(-1, amount)) {\n                state = LONG\n                holdPrice = r[l - 1].Close\n                $.PlotFlag(r[l - 1].Time, \'openLong\', \'L\')\n            }\n        } else if (down && (state == LONG || state == IDLE)) {\n            if (state == LONG && cover(exchange.Sell, "closebuy")) {\n                state = IDLE\n                holdPrice = 0\n                $.PlotFlag(r[l - 1].Time, \'coverLong\', \'CL\')\n            }\n            exchange.SetDirection("sell")\n            if (exchange.Sell(-1, amount)) {\n                state = SHORT\n                holdPrice = r[l - 1].Close\n                $.PlotFlag(r[l - 1].Time, \'openShort\', \'S\')\n            }\n        }\n        \n        // 止盈\n        if (state == LONG && r[l - 1].Close - holdPrice > profitTarget && cover(exchange.Sell, "closebuy")) {            \n            state = IDLE\n            holdPrice = 0\n            $.PlotFlag(r[l - 1].Time, \'coverLong\', \'CL\')\n        } else if (state == SHORT && holdPrice - r[l - 1].Close > profitTarget && cover(exchange.Buy, "closesell")) {            \n            state = IDLE\n            holdPrice = 0\n            $.PlotFlag(r[l - 1].Time, \'coverShort\', \'CS\')\n        }\n        LogStatus(_D())\n        Sleep(500)        \n    }\n}'

class FMZDeepPort:
    source_file = SOURCE_FILE
    source_features = SOURCE_FEATURES
    fidelity_notes = SOURCE_FIDELITY_NOTES
    javascript = ORIGINAL_JAVASCRIPT
    def run(self, adapter):
        runner = getattr(adapter, 'run_fmz_javascript', None)
        if runner is None:
            raise RuntimeError('This strategy needs an FMZ-compatible event/API adapter; refusing to invent OHLCV-only behavior.')
        return runner(self.javascript)
